const incoming = items && items[0] && items[0].json ? items[0].json : {};
const body = incoming.body || incoming;
const requestText = String(body.discovery_request || body.request || body.message || 'descubrir alcance tecnico para la siguiente HU');
const backlogId = String(body.backlog_id || body.backlogId || 'UNKNOWN').toUpperCase();
const repositories = body.repositories || ['central', 'sensors', 'web'];
const dryRun = body.dry_run !== false;
const prompt = [
  'Actua como AGENT-DISC-001 para el proyecto Invernadero Central.',
  'Solicitud: ' + requestText + '.',
  'backlog_id: ' + backlogId + '.',
  'Repositorios a considerar: ' + JSON.stringify(repositories) + '.',
  'Investiga primero y escribe despues. Identifica estructura real, entry points, dependencias directas, dependencias inversas, infraestructura, pruebas, documentacion, riesgos y unknowns.',
  'Clasifica cada afirmacion tecnica como CONFIRMED, DISCOVERED, INFERRED, PROPOSED o UNKNOWN. Nunca conviertas INFERRED o PROPOSED en DISCOVERED.',
  'Finaliza con sharedContract.recommended true|false y razones. No generes el contrato dentro de esta respuesta.',
  'Salida esperada: resumen_actual, arquitectura_involucrada, impact_map, change_inventory, dependencies, reverse_dependencies, infra_surface, test_surface, docs_surface, risks, unknowns, sharedContract.',
  'Trabaja en modo DRAFT/read-only; no persistas, no muevas Kanban, no marques DONE, no edites HU congeladas, no compres, no despliegues criticamente ni controles sistemas fisicos sin aprobacion humana.',
  'Si falta informacion critica, haz una sola pregunta.'
].join(' ');
return [{ json: { agent: 'project-discovery', workspace: 'central', prompt, mode: 'wf-technical-discovery-001', approval_required: true, dry_run: dryRun, metadata: { task_id: 'WF-TECH-DISCOVERY-001', agent_id: 'AGENT-DISC-001', backlog_id: backlogId, requested_by: body.requested_by || 'chat-gateway' } } }];
